// Build the modified_since timestamp (last 24 hours)
const since = new Date(Date.now() - 24 * 60 * 60 * 1000).toISOString();
return [{ json: { since } }];

// Filter OTX pulses to maritime-relevant ones and transform to MTS-OPS format

const MARITIME_KEYWORDS = [
  'maritime', 'shipping', 'vessel', 'port', 'offshore', 'ais',
  'gps spoofing', 'navy', 'coast guard', 'tanker', 'cargo', 'imo',
  'dnv', 'classification society', 'scada', 'ot security'
];

const VECTOR_MAP = [
  { keywords: ['ransomware'],          vector: 'Ransomware' },
  { keywords: ['phishing', 'spear'],   vector: 'Phishing' },
  { keywords: ['supply chain'],        vector: 'Supply Chain' },
  { keywords: ['ddos', 'denial'],      vector: 'DDoS' },
  { keywords: ['insider'],             vector: 'Insider Threat' },
  { keywords: ['iot', 'ot', 'scada', 'ics'], vector: 'IoT/OT Compromise' },
  { keywords: ['exploit', 'cve', 'vuln'], vector: 'Vulnerability Exploitation' },
  { keywords: ['intrusion', 'lateral'], vector: 'Network Intrusion' },
];

const SECTOR_KEYWORDS = [
  { keywords: ['maritime', 'shipping', 'vessel', 'port', 'tanker', 'cargo', 'offshore'], sector: 'Maritime' },
  { keywords: ['energy', 'oil', 'gas', 'power', 'grid'],    sector: 'Energy' },
  { keywords: ['transport', 'aviation', 'rail'],             sector: 'Transportation' },
  { keywords: ['water', 'utility'],                          sector: 'Water' },
  { keywords: ['health', 'hospital', 'medical'],             sector: 'Healthcare' },
  { keywords: ['bank', 'financial', 'fintech'],              sector: 'Financial' },
  { keywords: ['telecom', 'isp', 'satellite'],               sector: 'Telecom' },
  { keywords: ['government', 'military', 'defence', 'navy'], sector: 'Government' },
];

function detectVector(text) {
  const t = text.toLowerCase();
  for (const { keywords, vector } of VECTOR_MAP) {
    if (keywords.some(k => t.includes(k))) return vector;
  }
  return 'Malware';
}

function detectSector(text) {
  const t = text.toLowerCase();
  for (const { keywords, sector } of SECTOR_KEYWORDS) {
    if (keywords.some(k => t.includes(k))) return sector;
  }
  return 'Maritime'; // Default for this feed — if we're filtering to maritime pulses
}

const response = $input.first().json;
const pulses = (response.results || []);

const maritimePulses = pulses.filter(p => {
  const text = [
    p.name || '',
    p.description || '',
    ...(p.tags || []),
    ...(p.industries || [])
  ].join(' ').toLowerCase();
  return MARITIME_KEYWORDS.some(kw => text.includes(kw));
});

if (maritimePulses.length === 0) {
  return [{ json: { __skip: true } }];
}

return maritimePulses.map(p => {
  const indicators = p.indicators || [];
  const fullText = `${p.name} ${p.description || ''} ${(p.tags || []).join(' ')}`;

  const iocs = {
    ips: indicators
      .filter(i => i.type === 'IPv4' || i.type === 'IPv6')
      .map(i => i.indicator)
      .slice(0, 20),
    domains: indicators
      .filter(i => i.type === 'domain' || i.type === 'hostname')
      .map(i => i.indicator)
      .slice(0, 20),
    hashes: indicators
      .filter(i => ['FileHash-MD5', 'FileHash-SHA256', 'FileHash-SHA1'].includes(i.type))
      .map(i => i.indicator)
      .slice(0, 20),
    urls: indicators
      .filter(i => i.type === 'URL')
      .map(i => i.indicator)
      .slice(0, 10),
  };

  // Remove empty arrays
  Object.keys(iocs).forEach(k => { if (iocs[k].length === 0) delete iocs[k]; });

  return {
    json: {
      type: 'incident',
      data: {
        title: (p.name || 'OTX Pulse').slice(0, 200),
        severity: 'Medium',
        sector: detectSector(fullText),
        attack_vector: detectVector(fullText),
        description: p.description ? p.description.slice(0, 500) : null,
        iocs: Object.keys(iocs).length > 0 ? iocs : null,
        source_url: `https://otx.alienvault.com/pulse/${p.id}`,
      }
    }
  };
});
